const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
export function createInteractions({refresh,showAppStep,getAppStep,reduced}){
 const scene=document.querySelector('.hero-scene'),stage=document.querySelector('.vehicle-stage'),phone=document.querySelector('.phone');
 const state={orbit:0,orbitTarget:0,tiltX:0,tiltY:0,tiltTargetX:0,tiltTargetY:0,installments:12,manualPayment:false,manualHero:null};
 stage.insertAdjacentHTML('afterend','<div class="explore-controls"><span>ARRASTE PARA EXPLORAR</span><div><button type="button" data-orbit="-1" aria-label="Girar veículo à esquerda">↶</button><button type="button" data-orbit="1" aria-label="Girar veículo à direita">↷</button><button type="button" class="reset-view" aria-label="Restaurar posição do veículo">↺</button></div></div>');
 stage.setAttribute('aria-label','Explorar veículo: arraste horizontalmente ou use as setas do teclado');stage.setAttribute('role','group');stage.tabIndex=0;
 let previousTime=0;let drag=null;stage.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,start:state.orbitTarget};stage.setPointerCapture(e.pointerId);stage.classList.add('dragging')});
 stage.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;state.orbitTarget=clamp(drag.start+(e.clientX-drag.x)/230,-1.1,1.1);refresh()});
 const endDrag=()=>{drag=null;stage.classList.remove('dragging')};['pointerup','pointercancel','lostpointercapture'].forEach(event=>stage.addEventListener(event,endDrag));
 stage.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home'].includes(e.key))return;e.preventDefault();state.orbitTarget=e.key==='Home'?0:clamp(state.orbitTarget+(e.key==='ArrowRight'?.22:-.22),-1.1,1.1);refresh()});
 document.querySelectorAll('[data-orbit]').forEach(b=>b.addEventListener('click',()=>{state.orbitTarget=clamp(state.orbitTarget+Number(b.dataset.orbit)*.3,-1.1,1.1);refresh()}));document.querySelector('.reset-view').addEventListener('click',()=>{state.orbitTarget=0;refresh()});
 const names=['Veículo','Consulta','Débitos','Pagamento','Regularização'];scene.insertAdjacentHTML('beforeend',`<div class="chapter-controls" role="group" aria-label="Explorar etapas da jornada">${names.map((name,i)=>`<button type="button" data-chapter="${i}" aria-label="Etapa ${i+1}: ${name}" aria-pressed="${i===0}"><span>0${i+1}</span><i></i></button>`).join('')}</div><span class="debt-selection-note" role="status"></span><div class="scan-line" aria-hidden="true"></div><div class="scene-caption" aria-hidden="true"></div>`);
 document.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>{state.manualHero=Number(b.dataset.chapter)/4;refresh()}));['wheel','touchmove'].forEach(name=>addEventListener(name,event=>{if(event.target.closest?.('.vehicle-stage'))return;state.manualHero=null},{passive:true}));
 document.querySelectorAll('.debt-card').forEach(card=>{card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-pressed','true');card.setAttribute('aria-label',`${card.querySelector('strong').textContent}: selecionar na demonstração`);const toggle=()=>{const selected=card.getAttribute('aria-pressed')!=='true';card.setAttribute('aria-pressed',String(selected));card.querySelector('.debt-check').textContent=selected?'✓':'+';const count=document.querySelectorAll('.debt-card[aria-pressed="true"]').length;document.querySelector('.debt-selection-note').textContent=`${count} selecionado${count===1?'':'s'} · demonstração`;refresh()};card.addEventListener('click',toggle);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})});
 document.querySelector('.payment-visual').insertAdjacentHTML('beforeend',`<div class="payment-explorer"><div class="payment-explorer-label"><label for="installments">Explore o parcelamento</label><output for="installments" id="installment-value">12x</output></div><input id="installments" type="range" min="1" max="12" step="1" value="12" aria-valuetext="12 parcelas"><div class="payment-presets"><button type="button" data-installments="1" aria-pressed="false">1x</button><button type="button" data-installments="6" aria-pressed="false">6x</button><button type="button" data-installments="12" aria-pressed="true">12x</button></div><small>Demonstração visual do parcelamento</small></div>`);
 function setInstallments(value,manual=false){state.installments=clamp(Math.round(value),1,12);if(manual)state.manualPayment=true;const slider=document.querySelector('#installments');slider.value=state.installments;slider.setAttribute('aria-valuetext',`${state.installments} parcela${state.installments===1?'':'s'}`);slider.style.setProperty('--range-progress',`${(state.installments-1)/11*100}%`);document.querySelector('#installment-value').textContent=state.installments+'x';document.querySelector('.payment-card>strong').innerHTML=`${state.installments}<span>x</span>`;document.querySelectorAll('[data-installments]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.installments)===state.installments)));document.querySelectorAll('.installment-grid>span').forEach((el,i)=>{el.classList.toggle('installment-active',i<state.installments);el.style.opacity=i<state.installments?'1':'.22'});refresh()}
 document.querySelector('#installments').addEventListener('input',e=>setInstallments(Number(e.target.value),true));document.querySelectorAll('[data-installments]').forEach(b=>b.addEventListener('click',()=>setInstallments(Number(b.dataset.installments),true)));
 document.querySelector('.phone-scene').insertAdjacentHTML('beforeend','<div class="phone-controls" role="group" aria-label="Navegar na demonstração do aplicativo"><button type="button" data-phone-direction="-1" aria-label="Tela anterior do aplicativo">←</button><span id="phone-page" aria-live="polite">01 / 03</span><button type="button" data-phone-direction="1" aria-label="Próxima tela do aplicativo">→</button></div>');
 const changePhone=direction=>showAppStep((getAppStep()+direction+3)%3,true);document.querySelectorAll('[data-phone-direction]').forEach(b=>b.addEventListener('click',()=>changePhone(Number(b.dataset.phoneDirection))));
 phone.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||reduced.matches)return;const r=phone.getBoundingClientRect();state.tiltTargetX=-(e.clientY-r.top-r.height/2)/r.height*8;state.tiltTargetY=(e.clientX-r.left-r.width/2)/r.width*10;refresh()});phone.addEventListener('pointerleave',()=>{state.tiltTargetX=state.tiltTargetY=0;refresh()});
 let swipe=null;phone.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')swipe={x:e.clientX,y:e.clientY}});phone.addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))changePhone(dx<0?1:-1);swipe=null});phone.addEventListener('pointercancel',()=>{swipe=null});
 const rail=document.createElement('nav');rail.className='journey-navigation';rail.setAttribute('aria-label','Navegar pela experiência');rail.innerHTML=[['inicio','Consulta'],['parcelamento','Parcelamento'],['app','App'],['sobre','Passo a passo'],['ajuda','Dúvidas']].map(([id,label],i)=>`<a href="#${id}" data-section="${id}" aria-label="${label}"><span>${label}</span><i>${i+1}</i></a>`).join('');document.body.append(rail);
 const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
 document.querySelector('.payment-section').insertAdjacentHTML('afterend','<div class="journey-bridge" aria-hidden="true"><div class="container"><span>CONSULTAR</span><i></i><span>ESCOLHER</span><i></i><span>PARCELAR</span><i></i><span>CONTINUAR</span></div><div class="bridge-pulse"></div></div>');
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('in-view',e.isIntersecting)),{threshold:.13});document.querySelectorAll('.section-heading,.center-heading,.section-copy,.media-card,.testimonial,.final-cta').forEach(el=>{el.classList.add('motion-reveal');observer.observe(el)});
 setInstallments(12);
 return {state,setInstallments,tick(time){const delta=previousTime?Math.min(100,time-previousTime):16;previousTime=time;const speed=reduced.matches?1:1-Math.exp(-delta/75);state.damping=speed;for(const [key,target]of [['orbit','orbitTarget'],['tiltX','tiltTargetX'],['tiltY','tiltTargetY']]){state[key]+=(state[target]-state[key])*speed;if(Math.abs(state[target]-state[key])<.003)state[key]=state[target]}return Math.abs(state.orbitTarget-state.orbit)+Math.abs(state.tiltTargetX-state.tiltX)+Math.abs(state.tiltTargetY-state.tiltY)>.0001;}};
}
